contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0 && amount <= 1 ether);
        require(lockTime <= 1000000);
        require(address(this).balance >= amount);

        (uint beforeUnlockTime, uint beforeAccBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        c.Put{value: amount}(lockTime); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint afterUnlockTime, uint afterAccBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;

        assert(afterAccBalance >= beforeAccBalance && afterContractBalance >= beforeContractBalance);
    }

    receive() external payable {}
}

