pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 lockTime, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        amount = bound(amount, 1, 1);
        lockTime = bound(lockTime, 0, 1000000);
        vm.assume(address(this).balance >= amount);
        uint256 beforeUnlockTime;
        uint256 beforeAccBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlockTime = __r0; beforeAccBalance = __r1; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterUnlockTime;
        uint256 afterAccBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlockTime = __r0; afterAccBalance = __r1; } catch { return; }
        uint afterContractBalance = address(c).balance;
        assertTrue(afterAccBalance >= beforeAccBalance && afterContractBalance >= beforeContractBalance);
    }

    function testFuzz_run(uint256 lockTime, uint256 amount) public {
        _run(lockTime, amount);
    }

    receive() external payable {}
}
